/**
 * Slack surface for human-in-the-loop tool approvals.
 *
 * Or compose with {@link buildDefaultEvents} (or your own handlers). When
 * composing by hand, also set `slackChannel({ interactivity: true })` (or
 * `toolApprovals: true`) so Socket Mode routes Approve/Deny clicks —
 * otherwise cards post but button presses are ACKed and ignored:
 *
 * ```ts
 * events: {
 *   ...buildDefaultEvents({ credentials }),
 *   ...buildToolApprovalEvents({ credentials }),
 * }
 * ```
 *
 * Or opt in via `slackChannel({ toolApprovals: true })`.
 * Park/resume itself is the framework HITL primitive (`needsApproval`);
 * this pack only delivers Approve/Deny in Slack.
 */
import { postMessage, setThreadStatus, updateMessage } from "./api.js";
import { authThreadStatus, buildApprovalBlocks, buildAuthBlocks, buildResolvedApprovalBlocks, buildResolvedAuthBlocks, } from "./approvals.js";
import { SLACK_DEFAULT_LOADING_MESSAGES } from "./constants.js";
import { defaultSlackLog } from "./log.js";
/**
 * Stream-event handlers that post Block Kit Approve/Deny cards and
 * update them when approval is resolved (HTTP, playground, or Slack).
 */
export function buildToolApprovalEvents(options = {}) {
    const botToken = options.credentials?.botToken;
    const getLog = options.getLog ?? (() => defaultSlackLog);
    const status = options.status !== false;
    async function resolveChip(state) {
        if (state.channelId === null || state.threadTs === null) {
            return;
        }
        if (status) {
            await setThreadStatus({
                botToken,
                channelId: state.channelId,
                threadTs: state.threadTs,
                status: "Working…",
                loadingMessages: [...SLACK_DEFAULT_LOADING_MESSAGES],
            });
            return;
        }
        await setThreadStatus({
            botToken,
            channelId: state.channelId,
            threadTs: state.threadTs,
            status: "",
        });
    }
    return {
        async "action.approval_requested"(event, channel, ctx) {
            const log = getLog();
            const state = channel.state;
            if (state.channelId === null || state.threadTs === null) {
                return;
            }
            const blocks = buildApprovalBlocks({
                sessionId: ctx.session.id,
                callId: event.data.callId,
                toolName: event.data.toolName,
                args: event.data.args,
            });
            try {
                const posted = await postMessage({
                    botToken,
                    channel: state.channelId,
                    threadTs: state.threadTs,
                    text: `Approval required for \`${event.data.toolName}\``,
                    blocks,
                });
                channel.state.approvalMessageByCallId = {
                    ...(state.approvalMessageByCallId ?? {}),
                    [event.data.callId]: posted.ts,
                };
                if (status) {
                    // One entry: Slack cycles `loading_messages`, and filler such as
                    // "Thinking…" reads as work while nothing runs until the click.
                    await setThreadStatus({
                        botToken,
                        channelId: state.channelId,
                        threadTs: state.threadTs,
                        status: "Awaiting approval…",
                        loadingMessages: ["Awaiting approval…"],
                    });
                }
                log.info("approval card posted", {
                    call_id: event.data.callId,
                    tool: event.data.toolName,
                    message_ts: posted.ts,
                });
            }
            catch (error) {
                log.warn("approval card post failed", {
                    call_id: event.data.callId,
                    error: error instanceof Error ? error.message : String(error),
                });
            }
        },
        async "action.approval_resolved"(event, channel) {
            const log = getLog();
            const state = channel.state;
            const messageTs = state.approvalMessageByCallId?.[event.data.callId];
            if (state.channelId !== null && messageTs !== undefined && messageTs !== "") {
                const blocks = buildResolvedApprovalBlocks({
                    toolName: event.data.toolName,
                    decision: event.data.decision,
                    ...(event.data.by === undefined ? {} : { byUserId: event.data.by }),
                });
                const verb = event.data.decision === "approve" ? "Approved" : "Denied";
                await updateMessage({
                    botToken,
                    channel: state.channelId,
                    ts: messageTs,
                    text: `${verb} — ${event.data.toolName}`,
                    blocks,
                });
                const next = { ...(state.approvalMessageByCallId ?? {}) };
                delete next[event.data.callId];
                channel.state.approvalMessageByCallId = next;
            }
            await resolveChip(state);
            log.info("approval resolved in slack", {
                call_id: event.data.callId,
                decision: event.data.decision,
            });
        },
        async "action.auth_requested"(event, channel, ctx) {
            const log = getLog();
            const state = channel.state;
            if (state.channelId === null || state.threadTs === null) {
                return;
            }
            const blocks = buildAuthBlocks({
                sessionId: ctx.session.id,
                callId: event.data.callId,
                toolName: event.data.toolName,
                connection: event.data.connection,
                authUrl: event.data.authUrl,
            });
            try {
                const posted = await postMessage({
                    botToken,
                    channel: state.channelId,
                    threadTs: state.threadTs,
                    text: `Authorization required for \`${event.data.connection}\``,
                    blocks,
                });
                channel.state.approvalMessageByCallId = {
                    ...(state.approvalMessageByCallId ?? {}),
                    [event.data.callId]: posted.ts,
                };
                if (status) {
                    await setThreadStatus({
                        botToken,
                        channelId: state.channelId,
                        threadTs: state.threadTs,
                        status: authThreadStatus(event.data.connection),
                        // One entry, as for an approval card.
                        loadingMessages: [authThreadStatus(event.data.connection)],
                    });
                }
                log.info("auth card posted", {
                    call_id: event.data.callId,
                    connection: event.data.connection,
                    message_ts: posted.ts,
                });
            }
            catch (error) {
                log.warn("auth card post failed", {
                    call_id: event.data.callId,
                    error: error instanceof Error ? error.message : String(error),
                });
            }
        },
        async "action.auth_resolved"(event, channel) {
            const log = getLog();
            const state = channel.state;
            const messageTs = state.approvalMessageByCallId?.[event.data.callId];
            if (state.channelId !== null && messageTs !== undefined && messageTs !== "") {
                const blocks = buildResolvedAuthBlocks({
                    connection: event.data.connection,
                    decision: event.data.decision,
                    byUserId: event.data.by,
                });
                const verb = event.data.decision === "approve" ? "Connected" : "Cancelled";
                await updateMessage({
                    botToken,
                    channel: state.channelId,
                    ts: messageTs,
                    text: `${verb} — ${event.data.connection}`,
                    blocks,
                });
                const next = { ...(state.approvalMessageByCallId ?? {}) };
                delete next[event.data.callId];
                channel.state.approvalMessageByCallId = next;
            }
            await resolveChip(state);
            log.info("auth resolved in slack", {
                call_id: event.data.callId,
                decision: event.data.decision,
            });
        },
    };
}
